CREATE OR REPLACE FUNCTION public.create_community(p_handle text, p_name text, p_description text DEFAULT NULL::text, p_city text DEFAULT NULL::text, p_purpose text DEFAULT NULL::text, p_join_policy text DEFAULT 'open'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_id uuid;
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF NOT public.has_operator_grant(v_uid, 'community_leader') THEN
    RAISE EXCEPTION 'Community Leader grant required';
  END IF;
  IF p_join_policy NOT IN ('open', 'approval_required') THEN
    RAISE EXCEPTION 'join_policy must be open or approval_required';
  END IF;

  INSERT INTO communities (handle, name, description, city, purpose, join_policy, created_by)
  VALUES (p_handle, p_name, p_description, p_city, p_purpose, p_join_policy, v_uid)
  RETURNING id INTO v_id;

  INSERT INTO community_members (community_id, user_id, role, status, joined_at)
  VALUES (v_id, v_uid, 'leader', 'active', now());

  INSERT INTO community_blocks (community_id, block_type, position) VALUES
    (v_id, 'cover', 0),
    (v_id, 'header', 1),
    (v_id, 'about', 2),
    (v_id, 'events_auto', 3),
    (v_id, 'members_auto', 4);

  RETURN v_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.creator_page_member_eligibility_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_audience text;
BEGIN
 SELECT audience INTO v_audience FROM public.creator_page_publications WHERE page_id=NEW.community_id;
 IF v_audience IS NOT NULL AND NEW.status IN ('pending','active')
 AND NOT public.creator_page_audience_matches(v_audience,NEW.user_id) THEN
  RAISE EXCEPTION 'Community unavailable' USING ERRCODE='42501'; END IF;
 RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.ensure_creator_page_community(p_page_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE p public.creator_page_drafts; v_handle text;
BEGIN
 SELECT * INTO p FROM public.creator_page_drafts WHERE id=p_page_id FOR UPDATE;
 IF p.id IS NULL OR p.page_kind<>'community' THEN RAISE EXCEPTION 'Community page unavailable'; END IF;
 IF EXISTS(SELECT 1 FROM public.communities WHERE id=p.id) THEN
  IF NOT EXISTS(SELECT 1 FROM public.communities WHERE id=p.id AND created_by=p.owner_id) THEN RAISE EXCEPTION 'Page identity conflict'; END IF;
  RETURN p.id;
 END IF;
 v_handle := 'page-' || replace(p.id::text,'-','');
 INSERT INTO public.communities(id,handle,name,description,city,purpose,join_policy,created_by,status)
 VALUES(p.id,v_handle,p.page_data->>'name',p.page_data->>'description',p.page_data->>'city',p.page_data->>'purpose',
   coalesce(p.page_data->>'join_policy','open'),p.owner_id,'draft');
 INSERT INTO public.community_blocks(community_id,block_type,position) VALUES
 (p.id,'cover',0),(p.id,'header',1),(p.id,'about',2),(p.id,'events_auto',3),(p.id,'members_auto',4);
 RETURN p.id;
END;
$function$

CREATE OR REPLACE FUNCTION public.finalize_community_join(p_member_id uuid, p_actor_uid uuid, p_self boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_row record;
  v_community_name text;
  v_answers jsonb;
  v_first text;
  v_intro text;
  v_question text;
  v_qfrag text;
  v_area text;
  v_body text;
  v_posted boolean := false;
  v_standard boolean := false;
  v_intro_id uuid;
begin
  -- Same lock order as request/settings/review: community, then membership.
  perform 1 from public.communities where id=(select community_id from public.community_members where id=p_member_id) FOR UPDATE;
  select id, community_id, user_id, status into v_row
  from community_members where id = p_member_id FOR UPDATE;
  if v_row.id is null then
    raise exception 'That membership is gone.';
  end if;

  if v_row.status <> 'pending' then
    raise exception 'That request was already handled.';
  end if;

  select name into v_community_name from communities where id = v_row.community_id;

  v_standard := EXISTS(SELECT 1 FROM public.creator_page_publications WHERE page_id=v_row.community_id AND page_kind='community');
  IF v_standard THEN PERFORM public.ensure_community_chat_layout(v_row.community_id); END IF;

  update community_members
  set status = 'active', joined_at = now()
  where id = v_row.id;

  -- the system-composed intro card, into the main chat (zip never leaves
  -- community_member_answers; only the area name travels)
  select a.answers into v_answers
  from community_member_answers a where a.member_id = v_row.id;

  v_first := btrim(coalesce(v_answers->>'first_name', ''));
  v_intro := btrim(coalesce(v_answers->>'intro_answer', ''));
  if v_standard then
    -- The community lock covers the receipt decision, admission and insertion.
    -- Publish only the standard member-written answer; never derive an area or
    -- append a custom question/answer/contact field. Compatibility placeholders
    -- keep older renderers valid while the versioned renderer uses plain text.
    if NOT EXISTS(SELECT 1 FROM public.community_introduction_receipts WHERE community_id=v_row.community_id AND user_id=v_row.user_id) then
      if v_first='' or v_intro='' OR char_length(v_intro)>1000 then
        raise exception 'A standard introduction is required before admission';
      end if;
      insert into public.community_broadcasts(community_id,sender_id,body,kind,payload)
      values(v_row.community_id,v_row.user_id,v_intro,'intro',jsonb_build_object(
        'format','member_intro_v1','user_id',v_row.user_id,'first_name',v_first,
        'area',null,'question','Introduce yourself','answer',v_intro)) returning id into v_intro_id;
      insert into public.community_introduction_receipts(community_id,user_id,source_kind,source_id)
      values(v_row.community_id,v_row.user_id,'broadcast',v_intro_id);
      v_posted:=true;
    end if;
  elsif v_first <> '' and v_intro <> '' then
    v_question := coalesce(
      nullif(btrim(coalesce(v_answers->>'intro_question', '')), ''),
      nullif(btrim(coalesce((select join_intro_question from communities where id = v_row.community_id), '')), ''),
      'introduce yourself. what should this community know about you?'
    );
    v_qfrag := lower(regexp_replace(btrim(v_question), '[?.!]+$', ''));
    select za.area into v_area from zip_areas za where za.zip = v_answers->>'zip';

    v_body := 'this is ' || v_first
      || coalesce(', from ' || v_area, '')
      || '. ' || v_qfrag || ': ' || v_intro
      || case when v_intro ~ '[.!?]$' then '' else '.' end;

    insert into community_broadcasts (community_id, sender_id, body, kind, payload)
    values (
      v_row.community_id,
      v_row.user_id,
      v_body,
      'intro',
      jsonb_build_object(
        'user_id', v_row.user_id,
        'first_name', v_first,
        'area', v_area,
        'question', v_question,
        'answer', v_intro
      )
    );
    v_posted := true;
  end if;

  -- LIZ COPY. p_self = an open joiner letting themselves in; else a leader
  -- approved them. Only claim the intro is posted when it actually is.
  IF v_standard THEN
    PERFORM public.emit_creator_join_notice(v_row.id,'approved',p_actor_uid,'you''re in',case when p_self then 'you''re in at ' || v_community_name || case when v_posted then '. your introduction is already posted, come say hi.' else '. come say hi.' end else v_community_name || case when v_posted then ' let you in. your introduction is already posted, come say hi.' else ' let you in. come say hi.' end end);
  ELSE
  insert into app_notifications (user_id, type, title, body, actor_user_id)
  values (
    v_row.user_id,
    'community_join_approved',
    'you''re in',
    case when p_self
      then 'you''re in at ' || v_community_name || case when v_posted
        then '. your introduction is already posted, come say hi.'
        else '. come say hi.' end
      else v_community_name || case when v_posted
        then ' let you in. your introduction is already posted, come say hi.'
        else ' let you in. come say hi.' end
    end,
    p_actor_uid
  );
  END IF;
end;
$function$

CREATE OR REPLACE FUNCTION public.get_creator_page_join_settings(p_page_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE p public.creator_page_drafts; c public.communities; v_audience text; v_published boolean; v_name text;
BEGIN
 SELECT * INTO p FROM public.creator_page_drafts WHERE id=p_page_id;
 IF auth.uid() IS NULL OR p.id IS NULL OR p.owner_id<>auth.uid() OR p.page_kind<>'community'
 OR NOT public.creator_page_is_owned(p_page_id) THEN RAISE EXCEPTION 'Community page unavailable' USING ERRCODE='42501'; END IF;
 SELECT * INTO c FROM public.communities WHERE id=p.id;
 IF c.id IS NOT NULL AND c.created_by IS DISTINCT FROM p.owner_id THEN RAISE EXCEPTION 'Community page identity conflict' USING ERRCODE='42501'; END IF;
 SELECT audience,true,name INTO v_audience,v_published,v_name FROM public.creator_page_publications WHERE page_id=p.id;
 RETURN jsonb_build_object('page_id',p.id,'owner_id',p.owner_id,'name',coalesce(v_name,p.page_data->>'name'),
 'published',coalesce(v_published,false),'audience',coalesce(v_audience,p.page_data->>'audience','everyone'),
 'version',coalesce(c.creator_page_join_settings_version,0),
 'pending_count',(SELECT count(*) FROM public.community_members WHERE community_id=p.id AND status='pending'),
 'settings',jsonb_build_object('join_policy',coalesce(c.join_policy,p.page_data->>'join_policy','open'),
 'join_welcome_message',c.join_welcome_message,'join_intro_question',c.join_intro_question,'guidelines_url',c.guidelines_url,
 'join_ask_reason',coalesce(c.join_ask_reason,false),'join_ask_source',coalesce(c.join_ask_source,false),
 'join_ask_rules_confirm',coalesce(c.join_ask_rules_confirm,false),'join_open_question',c.join_open_question));
END;
$function$

CREATE OR REPLACE FUNCTION public.publish_creator_page(p_page_id uuid, p_submission_id uuid)
 RETURNS creator_page_publications
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE p public.creator_page_drafts; s public.creator_page_submissions; result public.creator_page_publications; v_audience text;
BEGIN
 SELECT * INTO p FROM public.creator_page_drafts WHERE id=p_page_id FOR UPDATE;
 IF auth.uid() IS NULL OR p.id IS NULL OR p.owner_id<>auth.uid() THEN RAISE EXCEPTION 'Page unavailable' USING ERRCODE='42501'; END IF;
 SELECT * INTO s FROM public.creator_page_submissions WHERE id=p_submission_id AND page_id=p.id FOR UPDATE;
 IF s.id IS NULL OR s.status<>'approved' THEN RAISE EXCEPTION 'This page needs approval before publication' USING ERRCODE='PT409'; END IF;
 v_audience := coalesce(s.page_snapshot->>'audience','everyone');
 IF NOT public.creator_page_audience_matches(v_audience,auth.uid()) THEN RAISE EXCEPTION 'Page unavailable' USING ERRCODE='42501'; END IF;
 SELECT * INTO result FROM public.creator_page_publications WHERE page_id=p.id;
 IF result.page_id IS NOT NULL THEN
  IF result.submission_id=s.id THEN RETURN result; END IF;
  RAISE EXCEPTION 'This page is already published. Use its page settings.' USING ERRCODE='PT409';
 END IF;
 IF s.revision<>(SELECT max(revision) FROM public.creator_page_submissions WHERE page_id=p.id)
 OR s.page_snapshot<>p.page_data THEN
  RAISE EXCEPTION 'Your current draft differs from the approved page. Review it before publishing.' USING ERRCODE='PT409';
 END IF;
 IF p.page_kind='community' THEN
  PERFORM public.creator_community_classification_validate(s.page_snapshot,true);
  PERFORM public.ensure_creator_page_community(p.id);
  INSERT INTO public.creator_page_discovery_publications(page_id,discovery_area,categories) VALUES(p.id,s.page_snapshot->>'discovery_area',ARRAY(SELECT jsonb_array_elements_text(s.page_snapshot->'categories')));
  UPDATE public.communities SET name=s.page_snapshot->>'name',description=s.page_snapshot->>'description',
   city=s.page_snapshot->>'city',purpose=s.page_snapshot->>'purpose',join_policy=CASE WHEN creator_page_join_settings_version>0 THEN join_policy ELSE coalesce(s.page_snapshot->>'join_policy','open') END
   WHERE id=p.id;
  UPDATE public.community_blocks SET content=jsonb_build_object('images',jsonb_build_array(s.page_snapshot->>'photo_url'))
   WHERE community_id=p.id AND block_type='cover' AND nullif(s.page_snapshot->>'photo_url','') IS NOT NULL;
 END IF;
 INSERT INTO public.creator_page_publications(page_id,submission_id,page_kind,owner_id,name,purpose,city,description,photo_url,audience)
 VALUES(p.id,s.id,p.page_kind,p.owner_id,s.page_snapshot->>'name',s.page_snapshot->>'purpose',s.page_snapshot->>'city',
   s.page_snapshot->>'description',s.page_snapshot->>'photo_url',v_audience) RETURNING * INTO result;
 IF p.page_kind='community' THEN
  UPDATE public.communities SET status='active' WHERE id=p.id;
  INSERT INTO public.community_members(community_id,user_id,role,status,joined_at) VALUES(p.id,p.owner_id,'leader','active',now());
 END IF;
 RETURN result;
END;
$function$

CREATE OR REPLACE FUNCTION public.request_to_join_community(p_community_id uuid, p_answers jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_community record;
  v_existing record;
  v_member_id uuid;
  v_first text;
  v_stored jsonb;
begin
  if v_uid is null then
    raise exception 'Not signed in';
  end if;

  select id, name, status, join_policy, join_intro_question, creator_page_join_settings_version, join_ask_reason, join_ask_source, join_ask_rules_confirm, join_open_question
  into v_community
  from communities where id = p_community_id AND public.creator_community_is_visible(id) FOR UPDATE;
  if v_community.id is null or v_community.status <> 'active' then
    raise exception 'That community is not open to joins right now.';
  end if;

  -- every field required, validated server-side (the popup mirrors this)
  if p_answers is null or jsonb_typeof(p_answers) <> 'object' then
    raise exception 'Answers are required.';
  end if;
  if coalesce(btrim(p_answers->>'first_name'), '') = ''
     or char_length(p_answers->>'first_name') > 100 then
    raise exception 'First name is required.';
  end if;
  if coalesce(btrim(p_answers->>'last_name'), '') = ''
     or char_length(p_answers->>'last_name') > 100 then
    raise exception 'Last name is required.';
  end if;
  if coalesce(btrim(p_answers->>'email'), '') = ''
     or p_answers->>'email' !~* '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'
     or char_length(p_answers->>'email') > 254 then
    raise exception 'A real email is required.';
  end if;
  if coalesce(btrim(p_answers->>'zip'), '') = ''
     or p_answers->>'zip' !~ '^[0-9]{5}$' then
    raise exception 'A 5 digit zip code is required.';
  end if;
  if coalesce(btrim(p_answers->>'intro_answer'), '') = ''
     or char_length(p_answers->>'intro_answer') > 1000 then
    raise exception 'Your introduction is required.';
  end if;
  if coalesce((p_answers->>'guidelines_accepted')::boolean, false) is not true then
    raise exception 'Accepting the community guidelines is required.';
  end if;

  -- Liz decision #11: each of these only applies -- and is only required --
  -- when THIS community has that slot turned on.
  if v_community.join_ask_reason and (
       coalesce(btrim(p_answers->>'reason_answer'), '') = ''
       or char_length(p_answers->>'reason_answer') > 1000
     ) then
    raise exception 'Tell us why you want to join.';
  end if;
  if v_community.join_ask_source and (
       coalesce(btrim(p_answers->>'source_answer'), '') = ''
       or char_length(p_answers->>'source_answer') > 500
     ) then
    raise exception 'Tell us how you heard about this community.';
  end if;
  if v_community.join_ask_rules_confirm
     and coalesce((p_answers->>'rules_confirmed')::boolean, false) is not true then
    raise exception 'Confirming you meet the membership requirement is required.';
  end if;
  if coalesce(btrim(v_community.join_open_question), '') <> '' and (
       coalesce(btrim(p_answers->>'open_answer'), '') = ''
       or char_length(p_answers->>'open_answer') > 1000
     ) then
    raise exception 'That answer is required.';
  end if;

  -- whitelist: store exactly the doc 09 keys, nothing else, plus whichever
  -- of the four new keys this community actually asks for
  v_stored := jsonb_build_object(
    'first_name', btrim(p_answers->>'first_name'),
    'last_name', btrim(p_answers->>'last_name'),
    'email', btrim(p_answers->>'email'),
    'zip', btrim(p_answers->>'zip'),
    'intro_answer', btrim(p_answers->>'intro_answer'),
    'intro_question', coalesce(nullif(btrim(v_community.join_intro_question), ''), 'introduce yourself. what should this community know about you?'),
    'open_question', nullif(btrim(v_community.join_open_question), ''),
    'joining_settings_version', v_community.creator_page_join_settings_version,
    'guidelines_accepted_at', now()
  );
  if v_community.join_ask_reason then
    v_stored := v_stored || jsonb_build_object('reason_answer', btrim(p_answers->>'reason_answer'));
  end if;
  if v_community.join_ask_source then
    v_stored := v_stored || jsonb_build_object('source_answer', btrim(p_answers->>'source_answer'));
  end if;
  if v_community.join_ask_rules_confirm then
    v_stored := v_stored || jsonb_build_object('rules_confirmed', true);
  end if;
  if coalesce(btrim(v_community.join_open_question), '') <> '' then
    v_stored := v_stored || jsonb_build_object('open_answer', btrim(p_answers->>'open_answer'));
  end if;

  select id, status into v_existing
  from community_members
  where community_id = p_community_id and user_id = v_uid FOR UPDATE;

  if v_existing.id is null then
    insert into community_members (community_id, user_id, role, status)
    values (p_community_id, v_uid, 'member', 'pending')
    returning id into v_member_id;
  elsif v_existing.status = 'left' then
    -- rejoining after leaving on good terms: same row back to pending
    update community_members
    set status = 'pending', joined_at = null
    where id = v_existing.id;
    v_member_id := v_existing.id;
  elsif v_existing.status = 'pending' then
    raise exception 'You already asked to join. The leader has your request.';
  elsif v_existing.status = 'active' then
    raise exception 'You are already a member.';
  else
    -- declined, removed, or banned: rejoin-after-decline is a logged open
    -- question, now revisitable thanks to the distinct 'declined' status
    raise exception 'You cannot join this community right now.';
  end if;

  -- answers land ONLY in the private table (leader-eyes-only by RLS)
  insert into community_member_answers (member_id, community_id, user_id, answers)
  values (v_member_id, p_community_id, v_uid, v_stored)
  on conflict (member_id)
  do update set answers = excluded.answers, updated_at = now();

  -- New published pages have verified page-audience guards. Reuse the
  -- existing activation/notification path only after all answers are stored.
  -- Legacy page admission remains unchanged pending its separate authority audit.
  if v_community.join_policy = 'open' AND EXISTS (
    SELECT 1 FROM public.creator_page_publications WHERE page_id=p_community_id AND page_kind='community'
  ) then
    perform public.finalize_community_join(v_member_id, v_uid, true);
    return;
  end if;

  -- tell every active leader and co-leader (LIZ COPY)
  v_first := v_stored->>'first_name';
  IF EXISTS(SELECT 1 FROM public.creator_page_publications WHERE page_id=p_community_id AND page_kind='community') THEN
    PERFORM public.emit_creator_join_notice(v_member_id,'request',v_uid,'someone wants in',v_first || ' asked to join ' || v_community.name || '. their introduction is waiting for you.');
  ELSE
  insert into app_notifications (user_id, type, title, body, actor_user_id)
  select m.user_id,
         'community_join_request',
         'someone wants in',
         v_first || ' asked to join ' || v_community.name || '. their introduction is waiting for you.',
         v_uid
  from community_members m
  where m.community_id = p_community_id
    and m.role in ('leader', 'co_leader')
    and m.status = 'active';
  END IF;
end;
$function$

CREATE OR REPLACE FUNCTION public.save_creator_page_join_settings(p_page_id uuid, p_expected_version integer, p_settings jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE current_settings jsonb; normalized jsonb; key text; value text;
BEGIN
 -- Same page lock order as publication/event preparation. No account-wide grant.
 PERFORM 1 FROM public.creator_page_drafts WHERE id=p_page_id FOR UPDATE;
 current_settings:=public.get_creator_page_join_settings(p_page_id);
 IF p_expected_version IS NULL OR p_expected_version<0 OR p_settings IS NULL OR jsonb_typeof(p_settings)<>'object'
 OR (SELECT count(*) FROM jsonb_object_keys(p_settings))<>8
 OR NOT p_settings ?& ARRAY['join_policy','join_welcome_message','join_intro_question','guidelines_url',
 'join_ask_reason','join_ask_source','join_ask_rules_confirm','join_open_question'] THEN
 RAISE EXCEPTION 'Check the joining settings' USING ERRCODE='22023'; END IF;
 IF p_settings->>'join_policy' NOT IN ('open','approval_required') OR jsonb_typeof(p_settings->'join_policy')<>'string' THEN
 RAISE EXCEPTION 'Choose whether new members need approval' USING ERRCODE='22023'; END IF;
 FOREACH key IN ARRAY ARRAY['join_ask_reason','join_ask_source','join_ask_rules_confirm'] LOOP
 IF jsonb_typeof(p_settings->key)<>'boolean' THEN RAISE EXCEPTION 'Check the question choices' USING ERRCODE='22023'; END IF;
 END LOOP;
 normalized:=p_settings;
 FOREACH key IN ARRAY ARRAY['join_welcome_message','join_intro_question','guidelines_url','join_open_question'] LOOP
 IF jsonb_typeof(p_settings->key) NOT IN ('string','null') THEN RAISE EXCEPTION 'Check the question text' USING ERRCODE='22023'; END IF;
 value:=nullif(btrim(p_settings->>key),'');
 IF (key='join_welcome_message' AND length(value)>1000) OR (key IN ('join_intro_question','join_open_question') AND length(value)>200)
 OR (key='guidelines_url' AND value IS NOT NULL AND value!~*'^https?://[^[:space:]]+$') THEN
 RAISE EXCEPTION 'Check the question text or guidelines link' USING ERRCODE='22023'; END IF;
 normalized:=jsonb_set(normalized,ARRAY[key],coalesce(to_jsonb(value),'null'::jsonb));
 END LOOP;
 IF (normalized->>'join_ask_rules_confirm')::boolean AND current_settings->>'audience'='everyone' THEN
 RAISE EXCEPTION 'Membership confirmation requires a restricted community' USING ERRCODE='22023'; END IF;
 -- Ensure the existing community row only on an explicit save, never on a read.
 PERFORM public.ensure_creator_page_community(p_page_id);
 PERFORM 1 FROM public.communities WHERE id=p_page_id FOR UPDATE;
 current_settings:=public.get_creator_page_join_settings(p_page_id);
 -- A current identical configuration is confirmed even after a lost response.
 -- This confirms current state, not a historical receipt or replay of old intent.
 IF current_settings->'settings'=normalized AND (current_settings->>'version')::integer>0 THEN RETURN current_settings; END IF;
 IF (current_settings->>'version')::integer<>p_expected_version THEN
 RAISE EXCEPTION 'Joining settings changed. Check the saved version before saving again.' USING ERRCODE='PT409'; END IF;
 UPDATE public.communities SET join_policy=normalized->>'join_policy',join_welcome_message=normalized->>'join_welcome_message',
 join_intro_question=normalized->>'join_intro_question',guidelines_url=normalized->>'guidelines_url',
 join_ask_reason=(normalized->>'join_ask_reason')::boolean,join_ask_source=(normalized->>'join_ask_source')::boolean,
 join_ask_rules_confirm=(normalized->>'join_ask_rules_confirm')::boolean,join_open_question=normalized->>'join_open_question',
 creator_page_join_settings_version=creator_page_join_settings_version+1 WHERE id=p_page_id;
 RETURN public.get_creator_page_join_settings(p_page_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.set_community_join_policy(p_community_id uuid, p_join_policy text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := (select auth.uid());
  v_ok boolean;
begin
  if v_uid is null then
    raise exception 'Not signed in';
  end if;
  if p_join_policy not in ('approval_required', 'open') then
    raise exception 'Unknown join policy %', coalesce(p_join_policy, '(none)');
  end if;
  select (
      is_community_leader(p_community_id, v_uid)
      or is_admin(v_uid)
      or has_role(v_uid, 'admin'::app_role)
    )
    into v_ok;
  if v_ok is distinct from true then
    raise exception 'Not the leader of this community';
  end if;
  update public.communities set join_policy = p_join_policy where id = p_community_id;
end;
$function$
